/**
 * Switching a notebook to the pair its words are written in: the tap
 * behind every "Use English → Chinese" (the import check, the notebook's
 * line, the add sheet). It goes through the same path as changing the
 * languages in Settings: `updateNotebook`, queued and synced, after the
 * same Pro rule (`changeNeedsPro`), so a suggestion can never do what the
 * learner could not do by hand.
 */
import { changeNeedsPro, useBilling } from '@/features/billing/state.js';
import { listNotebooks } from '@/db/repo.js';
import { updateNotebook } from '@/db/mutations.js';
import { getMeta, setMeta, type StoredNotebook } from '@/db/schema.js';
import { syncSoon } from '@/sync/store.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import type { Pair } from './pairGuess.js';

/**
 * "English → Chinese", the way the app names a notebook's pair. The spaces
 * around the arrow do not break, so a pair never splits across two lines.
 */
export function pairName(pair: Pair): string {
  return `${LANGUAGE_NAMES[pair.targetLang]}\u00A0→\u00A0${LANGUAGE_NAMES[pair.meaningLang]}`;
}

export type PairChange = 'changed' | 'needsPro' | 'notYours';

/** Whether this notebook's languages are the learner's to change. */
export function ownsPair(notebook: Pick<StoredNotebook, 'role'>): boolean {
  return notebook.role === 'owner';
}

/** Changes the notebook's two languages, or says why it may not. */
export async function changePair(notebook: StoredNotebook, pair: Pair): Promise<PairChange> {
  if (!ownsPair(notebook)) return 'notYours';
  const others = (await listNotebooks()).filter(
    (one) => one.id !== notebook.id && one.role === 'owner',
  ).length;
  if (changeNeedsPro(useBilling.getState().state, others, notebook, pair) !== undefined) return 'needsPro';
  await updateNotebook(notebook.id, { targetLang: pair.targetLang, meaningLang: pair.meaningLang });
  void syncSoon();
  return 'changed';
}

/** Puts the pair suggestion away for this notebook on this device (meta `pairHints`). */
export async function dismissPairHint(notebookId: string): Promise<void> {
  const hints = await getMeta('pairHints');
  await setMeta('pairHints', { ...hints, [notebookId]: 'dismissed' });
}
